'use strict';

// MAIN //

/**
* Decomposes the sequence length into its prime factors.
*
* @private
* @param {number} n - length of the sequence
* @param {Int32Array} ifac - array to store the factors
* @param {Array<number>} ntryh - array of initial trial divisors
* @returns {number} status code
*/
function decompose( n, ifac, ntryh ) {
	var ntry;
	var nl;
	var nf;
	var nq;
	var nr;
	var ib;
	var i;
	var j;

	ntry = 0;
	nl = n;
	nf = 0;
	j = 0;
	do {
		if ( j < 4 ) {
			ntry = ntryh[ j ];
		} else {
			ntry += 2;
		}
		j += 1;
		while ( true ) {
			nq = nl / ntry;
			nr = nl - ( ntry * nq );
			if ( nr !== 0 ) {
				break;
			}
			nf += 1;
			ifac[ nf + 2 ] = ntry;
			nl = nq;
			if ( ntry === 2 && nf !== 1 ) {
				for ( i = 2; i <= nf; i++ ) {
					ib = nf - i + 2;
					ifac[ ib + 2 ] = ifac[ ib + 1 ];
				}
				ifac[ 3 ] = 2;
			}
			if ( nl === 1 ) {
				break;
			}
		}
	} while ( nl !== 1 );
	ifac[ 1 ] = n;
	ifac[ 2 ] = nf;
	return nf;
}


// EXPORTS //

module.exports = decompose;
